  const bgColors = ['bg-[#FDFBF7]', 'bg-[#F5F1E9]', 'bg-[#F0EEEB]', 'bg-[#EAE7E4]'];
  const bgColor = bgColors[parseInt(product.id) % bgColors.length];

  const tagColor = product.tag === 'Offer' ? 'bg-[#C5A059]' : 'bg-black';

  return (
    <div 
      className={`group relative rounded-2xl p-4 transition-all duration-500 luxury-transition ${bgColor} ${isHovered ? 'shadow-2xl -translate-y-2' : 'shadow-sm'}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Badge Tag */}
      {product.tag !== 'None' && (
        <div className="absolute top-6 left-6 z-10">
          <span className={`${tagColor} text-white text-[10px] px-3 py-1 uppercase tracking-widest font-bold rounded-full shadow-sm`}>
            {product.tag}
          </span>
        </div>
      )}

      {/* Wishlist Button */}
      <button 
        onClick={(e) => { e.preventDefault(); toggleWishlist(product.id); }}
        className={`absolute top-6 right-6 z-10 p-2.5 rounded-full transition-all duration-300 glass-effect ${isWishlisted ? 'text-[#C5A059]' : 'text-gray-400 hover:text-black hover:scale-110'}`}
      >
        <Heart fill={isWishlisted ? "currentColor" : "none"} className="w-5 h-5" />
      </button>

      {/* Image Gallery Container */}
      <Link to={`/product/${product.id}`} className="block aspect-square rounded-xl overflow-hidden mb-6 bg-white/40 backdrop-blur-sm">
        <img 
          src={product.images[0]} 
          alt={product.name}
          className={`w-full h-full object-contain p-8 luxury-transition duration-1000 ${isHovered ? 'scale-110' : 'scale-100'}`}
        />
      </Link>

      {/* Content */}
      <div className="px-2 pb-2">
        <div className="flex justify-between items-start mb-2">
          <div>
            <h3 className="font-serif text-xl mb-1 group-hover:text-[#C5A059] transition-colors">{product.name}</h3>
            <span className="text-[10px] uppercase tracking-widest text-gray-400 font-bold">{product.category}</span>
          </div>
          <div className="text-right">
            <p className="text-lg font-medium">${product.price.toLocaleString()}</p>
            {product.originalPrice && (
              <p className="text-xs text-gray-400 line-through">${product.originalPrice.toLocaleString()}</p>
            )}
          </div>
        </div>

        {/* Action Button */}
        <button 
          onClick={(e) => { e.preventDefault(); addToCart(product); }}
          className={`w-full mt-4 py-3.5 rounded-xl uppercase text-[10px] font-bold tracking-[0.2em] transition-all duration-500 flex items-center justify-center space-x-3 
            ${isHovered ? 'bg-black text-white' : 'bg-transparent border border-black text-black'}`}
        >
          <ShoppingBag className="w-4 h-4" />
          <span>Quick Buy</span>
        </button>
      </div>
    </div>
  );
};

