                  onClick={() => setActiveTab(tab)}
                  className={`text-[10px] uppercase font-bold tracking-[0.3em] whitespace-nowrap transition-all duration-300 relative pb-4 
                    ${activeTab === tab ? 'text-black' : 'text-gray-400 hover:text-black'}`}
                >
                  {tab}
