import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Product } from '../types';
import { useStore } from '../store';
import { Heart, ShoppingBag } from './Icons';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { toggleWishlist, wishlist } = useStore();
  const [isHovered, setIsHovered] = useState(false);
  const navigate = useNavigate();

  const isWishlisted = wishlist.includes(product.id);

  // Luxury pastel backgrounds based on ID for visual variety
  const bgColors = ['bg-[#FDFBF7]', 'bg-[#F5F1E9]', 'bg-[#F0EEEB]', 'bg-[#EAE7E4]'];
  const bgColor = bgColors[parseInt(product.id) % bgColors.length];

  const tagColor = product.tag === 'Offer' ? 'bg-[#C5A059]' : 'bg-black';

  const handlePurchaseClick = (e: React.MouseEvent) => {
    e.preventDefault();
    navigate(`/product/${product.id}`);
  };

  return (
    <div 
      className={`group relative rounded-3xl p-5 transition-all duration-700 ease-[cubic-bezier(0.23,1,0.32,1)] ${bgColor} ${
        isHovered 
          ? 'shadow-[0_30px_60px_-15px_rgba(0,0,0,0.1)] -translate-y-3' 
          : 'shadow-sm'
      }`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Badge Tag */}
      {product.tag !== 'None' && (
        <div className="absolute top-7 left-7 z-10">
          <span className={`${tagColor} text-white text-[9px] px-3.5 py-1.5 uppercase tracking-[0.15em] font-bold rounded-full shadow-md`}>
            {product.tag}
          </span>
        </div>
      )}

      {/* Wishlist Button */}
      <button 
        onClick={(e) => { e.preventDefault(); toggleWishlist(product.id); }}
        className={`absolute top-7 right-7 z-10 p-3 rounded-full transition-all duration-500 glass-effect border border-transparent ${
          isWishlisted 
            ? 'text-[#C5A059] border-[#C5A059]/20 shadow-inner' 
            : 'text-gray-400 hover:text-black hover:scale-110 hover:border-black/5 hover:shadow-lg'
        }`}
      >
        <Heart fill={isWishlisted ? "currentColor" : "none"} className="w-5 h-5" />
      </button>

      {/* Image Gallery Container */}
      <Link 
        to={`/product/${product.id}`} 
        className="block aspect-square rounded-2xl overflow-hidden mb-8 bg-white/40 backdrop-blur-sm relative"
      >
        <img 
          src={product.images[0]} 
          alt={product.name}
          className={`w-full h-full object-contain p-10 transition-transform duration-[1200ms] cubic-bezier(0.2, 0.8, 0.2, 1) ${
            isHovered ? 'scale-105 brightness-[1.02]' : 'scale-100'
          }`}
        />
        {/* Subtle Overlay on Hover */}
        <div className={`absolute inset-0 bg-black/5 opacity-0 transition-opacity duration-700 ${isHovered ? 'opacity-100' : ''}`} />
      </Link>

      {/* Content */}
      <div className="px-1 pb-1">
        <div className="flex justify-between items-start mb-3">
          <div>
            <h3 className="font-serif text-2xl mb-1.5 group-hover:text-[#C5A059] transition-colors duration-500">{product.name}</h3>
            <span className="text-[10px] uppercase tracking-[0.2em] text-gray-400 font-bold block">{product.category}</span>
          </div>
          <div className="text-right">
            <p className="text-xl font-light tracking-tight">${product.price.toLocaleString()}</p>
            {product.originalPrice && (
              <p className="text-xs text-gray-400 line-through mt-0.5">${product.originalPrice.toLocaleString()}</p>
            )}
          </div>
        </div>

        {/* Action Button */}
        <button 
          onClick={handlePurchaseClick}
          className={`w-full mt-6 py-4 rounded-2xl uppercase text-[10px] font-bold tracking-[0.25em] transition-all duration-500 flex items-center justify-center space-x-3 
