                  </div>

                  <button 
                    onClick={handleAddToCart}
                    className="flex-1 w-full bg-[#2C2A28] text-white py-6 px-12 rounded-2xl uppercase text-[10px] font-bold tracking-[0.5em] hover:bg-[#C5A059] hover:shadow-[0_25px_50px_-12px_rgba(197,160,89,0.5)] transition-all duration-700 flex items-center justify-center space-x-4 shadow-2xl group active:scale-[0.98]"
