                  </div>
                  <div className="text-center">
                    <span className="block text-[8px] font-bold uppercase tracking-[0.3em] text-[#C5A059] mb-2">Assurance</span>
                    <span className="text-[9px] text-gray-400 uppercase tracking-widest font-medium">Lifetime Care</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
