        {/* Specifications Drawer-style Section */}
        <section className="mb-32 grid grid-cols-1 lg:grid-cols-12 gap-16 border-t border-[#F5F1E9] pt-24 animate-fadeIn">
          <div className="lg:col-span-4">
             <h2 className="text-4xl font-serif text-[#2C2A28] mb-8">The Craftsmanship</h2>
             <p className="text-gray-500 text-lg font-light leading-relaxed mb-10 italic">
               "Horology is the intersection of architecture, engineering, and history. Every AEVO timepiece is a legacy waiting to be told."
             </p>
             <button className="text-[10px] font-bold uppercase tracking-[0.3em] border-b border-[#2C2A28] pb-1 hover:text-[#C5A059] hover:border-[#C5A059] transition-all">Download Technical Dossier</button>
          </div>
          <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-x-16 gap-y-10">
            {Object.entries(product.specs).map(([key, value]) => (
              <div key={key} className="group pb-6 border-b border-[#F5F1E9] transition-all hover:border-[#C5A059]">
                <dt className="text-gray-400 uppercase text-[9px] font-bold tracking-[0.2em] mb-2 group-hover:text-[#C5A059] transition-colors">{key}</dt>
                <dd className="text-sm font-medium text-[#2C2A28] tracking-tight">{value}</dd>
              </div>
            ))}
            <div className="group pb-6 border-b border-[#F5F1E9] transition-all hover:border-[#C5A059]">
              <dt className="text-gray-400 uppercase text-[9px] font-bold tracking-[0.2em] mb-2 group-hover:text-[#C5A059] transition-colors">Movement Origin</dt>
              <dd className="text-sm font-medium text-[#2C2A28] tracking-tight">Swiss Caliber AE-Elite</dd>
            </div>
            <div className="group pb-6 border-b border-[#F5F1E9] transition-all hover:border-[#C5A059]">
              <dt className="text-gray-400 uppercase text-[9px] font-bold tracking-[0.2em] mb-2 group-hover:text-[#C5A059] transition-colors">Boutique Service</dt>
              <dd className="text-sm font-medium text-[#2C2A28] tracking-tight">Priority Artisan Access</dd>
            </div>
          </div>
        </section>

        {/* Story Section */}
        <section className="mb-40 py-32 px-12 bg-white rounded-[4rem] border border-[#F5F1E9] text-center max-w-6xl mx-auto shadow-sm overflow-hidden relative">
          <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-[#C5A059]/20 to-transparent" />
          <span className="text-[#C5A059] uppercase text-[10px] font-bold tracking-[0.6em] mb-10 block">Artisan Philosophy</span>
          <h2 className="text-5xl md:text-6xl font-serif mb-12 italic text-[#2C2A28]">"Elegance is not being noticed, but being remembered."</h2>
          <p className="text-gray-400 text-xl leading-relaxed max-w-3xl mx-auto font-light mb-16">
            In our Genevan workshops, we don't just assemble parts; we curate moments. Each {product.name} undergoes 300 hours of stress testing and hand-finishing to ensure that your legacy is captured in every vibration of the balance wheel.
          </p>
          <div className="flex justify-center items-center space-x-16 opacity-30 grayscale">
             <img src="https://images.unsplash.com/photo-1542496658-e33a6d0d50f6?auto=format&fit=crop&q=80&w=100" className="h-12 w-auto object-contain" alt="Emblem 1" />
             <img src="https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=100" className="h-12 w-auto object-contain" alt="Emblem 2" />
             <img src="https://images.unsplash.com/photo-1508057198894-247b23fe5ade?auto=format&fit=crop&q=80&w=100" className="h-12 w-auto object-contain" alt="Emblem 3" />
          </div>
        </section>

        {/* Curated Recommendations */}
        {relatedProducts.length > 0 && (
          <section className="pt-32 border-t border-[#F5F1E9]">
            <div className="flex flex-col md:flex-row justify-between items-end mb-20 gap-8">
              <div>
                <span className="text-[#C5A059] uppercase text-[10px] font-bold tracking-[0.4em] mb-4 block">Recommended for You</span>
                <h2 className="text-5xl font-serif text-[#2C2A28]">Complementary Designs</h2>
              </div>
              <Link to="/shop" className="text-[10px] font-bold uppercase tracking-[0.4em] border-b border-[#2C2A28] pb-2 hover:text-[#C5A059] hover:border-[#C5A059] transition-all duration-500">View Full Collection</Link>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12">
              {relatedProducts.map(p => <ProductCard key={p.id} product={p} />)}
            </div>
          </section>
        )}
      </div>
    </div>
  );
};

