              {/* Footer Actions */}
              <div className="pt-8 space-y-10 animate-fadeInUp" style={{ animationDelay: '0.4s' }}>
                <div className="flex flex-col sm:flex-row items-center space-y-6 sm:space-y-0 sm:space-x-8">
                  <div className="flex items-center border border-[#F5F1E9] rounded-2xl bg-white shadow-sm p-1.5 h-16">
