};

export default ProductDetail;

import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useStore } from '../store';
import { Star, ShoppingBag, Heart, Share, ChevronLeft, ChevronRight } from '../components/Icons';
import ProductCard from '../components/ProductCard';

const ProductDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const { products, addToCart, toggleWishlist, wishlist } = useStore();
  const [activeImage, setActiveImage] = useState(0);
  const [quantity, setQuantity] = useState(1);
  const [shareFeedback, setShareFeedback] = useState(false);
  const [isConfiguring, setIsConfiguring] = useState(false);

  // Customization State
  const [engraving, setEngraving] = useState('');
  const [engravingStyle, setEngravingStyle] = useState('Serif');
  const [packaging, setPackaging] = useState('standard');
  const [extendedWarranty, setExtendedWarranty] = useState(false);
  const [selectedStrap, setSelectedStrap] = useState('Italian Leather');
  const [selectedDial, setSelectedDial] = useState('Midnight');

  const product = products.find(p => p.id === id);
  if (!product) return <div className="pt-40 text-center font-serif text-2xl">Masterpiece not found.</div>;

  const isWishlisted = wishlist.includes(product.id);
  const relatedProducts = products.filter(p => p.category === product.category && p.id !== product.id).slice(0, 4);

  const strapOptions = [
    { name: 'Italian Leather', description: 'Artisan hand-stitched calfskin.', price: 0 },
    { name: 'Milanese Mesh', description: 'Fluid stainless steel weave.', price: 150 },
    { name: 'Brushed Steel', description: 'Robust architectural bracelet.', price: 200 },
  ];

  const dialOptions = [
    { name: 'Midnight', hex: '#1A1A1A', description: 'Deep obsidian matte' },
    { name: 'Ivory', hex: '#FDFBF7', description: 'Classic bone enamel' },
    { name: 'Champagne', hex: '#E2D1B3', description: 'Sunray sunburst gold' },
    { name: 'Slate', hex: '#4A4A4A', description: 'Metallic brushed grey' },
  ];

  const engravingStyles = [
    { name: 'Serif', font: 'font-serif', label: 'Classic Heritage' },
    { name: 'Sans', font: 'font-sans', label: 'Modern Minimal' },
    { name: 'Script', font: 'italic font-serif', label: 'Artisan Script' },
  ];

  // Trigger feedback animation on configuration change
  useEffect(() => {
    setIsConfiguring(true);
    const timer = setTimeout(() => setIsConfiguring(false), 600);
    return () => clearTimeout(timer);
  }, [selectedStrap, selectedDial, engraving, engravingStyle, packaging, extendedWarranty]);

  const handleShare = async () => {
    const shareData = {
      title: `AEVO | ${product.name}`,
      text: `Discover the ${product.name} at AEVO Horology.`,
      url: window.location.href,
    };

    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.error('Sharing failed', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      setShareFeedback(true);
      setTimeout(() => setShareFeedback(false), 3000);
    }
  };

  const calculateTotalPrice = () => {
    const strapPrice = strapOptions.find(s => s.name === selectedStrap)?.price || 0;
    const warrantyPrice = extendedWarranty ? 250 : 0;
    return product.price + strapPrice + warrantyPrice;
  };

  const handleAddToCart = () => {
    addToCart(product, quantity);
    const summary = `
      Confirmed Reservation:
      Item: ${product.name}
      Quantity: ${quantity}
      Dial: ${selectedDial}
      Strap: ${selectedStrap}
      Personalization: ${engraving || 'None'} (${engravingStyle} Style)
      Packaging: ${packaging === 'premium' ? 'Signature Gift Box' : 'Standard'}
      Protection: ${extendedWarranty ? 'Care+ Active' : 'Standard'}
      Total: $${(calculateTotalPrice() * quantity).toLocaleString()}
    `;
    alert(summary);
  };

  return (
    <div className="pt-32 pb-20 bg-[#FDFBF7]">
      <div className="container mx-auto px-6 max-w-7xl">
        {/* Breadcrumbs */}
        <nav className="flex items-center space-x-3 text-[9px] uppercase tracking-[0.4em] text-gray-400 mb-16 animate-fadeIn">
          <Link to="/" className="hover:text-black transition-colors">Home</Link>
          <span className="opacity-30">/</span>
          <Link to="/shop" className="hover:text-black transition-colors">Collection</Link>
          <span className="opacity-30">/</span>
          <span className="text-black font-semibold">{product.name}</span>
        </nav>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 xl:gap-24 mb-32">
          {/* Gallery Section */}
          <div className="space-y-8 lg:sticky lg:top-32 h-fit">
            <div className="aspect-[4/5] bg-white rounded-[2.5rem] overflow-hidden relative group shadow-sm border border-[#F5F1E9]">
              <img 
                src={product.images[activeImage]} 
                alt={product.name} 
                className="w-full h-full object-contain p-12 transition-transform duration-[2000ms] ease-out group-hover:scale-110" 
              />

              {product.images.length > 1 && (
                <div className="absolute inset-0 flex items-center justify-between px-6 opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                  <button 
                    onClick={() => setActiveImage(prev => (prev - 1 + product.images.length) % product.images.length)} 
                    className="p-4 bg-white/90 backdrop-blur-xl rounded-full shadow-2xl hover:bg-white transition-all transform hover:-translate-x-1 active:scale-90"
                  >
                    <ChevronLeft className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => setActiveImage(prev => (prev + 1) % product.images.length)} 
                    className="p-4 bg-white/90 backdrop-blur-xl rounded-full shadow-2xl hover:bg-white transition-all transform hover:translate-x-1 active:scale-90"
                  >
                    <ChevronRight className="w-5 h-5" />
                  </button>
                </div>
              )}
            </div>

            <div className="flex justify-center items-center space-x-5">
              {product.images.map((img, i) => (
                <button 
                  key={i} 
                  onClick={() => setActiveImage(i)}
                  className={`w-20 h-24 overflow-hidden rounded-2xl border-2 transition-all p-2 duration-500 ${
                    i === activeImage 
                    ? 'border-[#C5A059] bg-white shadow-xl scale-105' 
                    : 'border-transparent opacity-40 hover:opacity-80 bg-white/50'
                  }`}
                >
                  <img src={img} alt={product.name} className="w-full h-full object-contain" />
                </button>
              ))}
            </div>
          </div>

          {/* Configuration Section */}
          <div className="flex flex-col">
            <div className="mb-10">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center space-x-4">
                  <span className="text-[#C5A059] uppercase text-[10px] font-bold tracking-[0.5em]">{product.category}</span>
                  {product.tag !== 'None' && (
                    <span className="bg-[#2C2A28] text-white text-[8px] px-3 py-1 rounded-full uppercase tracking-widest font-bold shadow-lg">{product.tag}</span>
                  )}
                </div>
                <div className="flex items-center space-x-4">
                  <button 
                    onClick={handleShare}
                    className="p-4 border border-[#F5F1E9] text-gray-400 rounded-full hover:text-black hover:border-black transition-all duration-500 relative group"
                    title="Share this masterpiece"
                  >
                    <Share className="w-5 h-5" />
                    {shareFeedback && (
                      <span className="absolute -bottom-10 left-1/2 -translate-x-1/2 text-[8px] uppercase tracking-widest font-bold text-[#C5A059] whitespace-nowrap animate-fadeIn">
                        Link Copied
                      </span>
                    )}
                  </button>
                  <button 
                    onClick={() => toggleWishlist(product.id)} 
                    className={`p-4 border rounded-full transition-all duration-700 ${
                      isWishlisted 
                      ? 'bg-[#C5A059] border-[#C5A059] text-white shadow-2xl scale-110' 
                      : 'border-[#F5F1E9] text-gray-300 hover:text-black hover:border-black'
                    }`}
                  >
                    <Heart fill={isWishlisted ? 'currentColor' : 'none'} className="w-5 h-5" />
                  </button>
                </div>
              </div>
              <h1 className="text-5xl md:text-6xl xl:text-7xl font-serif leading-[1.1] text-[#2C2A28] mb-6">{product.name}</h1>
              <div className="flex items-center space-x-8">
                <div className="flex text-[#C5A059] space-x-1">
                  {[1, 2, 3, 4, 5].map(s => <Star key={s} fill={s <= Math.floor(product.rating) ? 'currentColor' : 'none'} className="w-4 h-4" />)}
                </div>
                <span className="text-[9px] text-gray-400 uppercase tracking-[0.3em] font-bold">Authenticated Piece No. {product.id}</span>
              </div>
            </div>

            <div className="mb-12 flex items-baseline justify-between border-b border-[#F5F1E9] pb-8">
              <div className="flex items-baseline space-x-5">
                <span className={`text-4xl font-light tracking-tighter text-[#2C2A28] transition-transform duration-500 ${isConfiguring ? 'scale-105 text-[#C5A059]' : 'scale-100'}`}>
                  ${calculateTotalPrice().toLocaleString()}
                </span>
                {product.originalPrice && (
                  <span className="text-lg text-gray-300 line-through font-light">${product.originalPrice.toLocaleString()}</span>
                )}
              </div>
              <span className="text-[10px] text-green-600 uppercase tracking-[0.2em] font-bold">Limited Availability</span>
            </div>

            {/* Customization Controls */}
            <div className="space-y-14">
              {/* Dial Finish */}
              <div className="animate-fadeInUp" style={{ animationDelay: '0.1s' }}>
                <div className="flex justify-between items-center mb-6">
                  <label className="text-[10px] font-bold uppercase tracking-[0.4em] text-gray-400">1. Dial Selection</label>
                  <span className={`text-[10px] text-black uppercase tracking-widest font-bold transition-all duration-300 ${isConfiguring ? 'opacity-40 translate-x-2' : 'opacity-100 translate-x-0'}`}>{selectedDial}</span>
                </div>
                <div className="flex space-x-6">
                  {dialOptions.map((opt) => (
                    <button
                      key={opt.name}
                      onClick={() => setSelectedDial(opt.name)}
                      className="group relative"
                      title={opt.description}
                    >
                      <div 
                        className={`w-12 h-12 rounded-full border-2 transition-all duration-500 flex items-center justify-center p-0.5 ${
                          selectedDial === opt.name 
                          ? 'border-[#C5A059] shadow-lg scale-110' 
