          <span className="text-black font-bold">{product.name}</span>
        </nav>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 xl:gap-32 mb-40">
          {/* Gallery Section */}
          <div className="space-y-10 lg:sticky lg:top-32 h-fit">
