        {/* Technicals */}
        <div className="mb-40">
           <div className="flex items-center space-x-6 mb-12">
             <h2 className="text-4xl font-serif text-[#2C2A28]">Technical Dossier</h2>
             <div className="h-px flex-1 bg-[#F5F1E9]" />
