import React, { useState } from 'react';
import { useStore } from '../../store';
import { Product, Category, ProductTag } from '../../types';
import { X, Search } from '../../components/Icons';

const AdminProducts: React.FC = () => {
  // Fix: useStore provides upsertProduct, not addProduct/updateProduct
  const { products, upsertProduct, deleteProduct } = useStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    price: 0,
    category: 'Men',
    tag: 'None',
    description: '',
    stock: 0,
    images: ['https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=1000'],
    specs: {}
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      // Fix: updateProduct -> upsertProduct
      upsertProduct({ ...editingProduct, ...formData } as Product);
    } else {
      // Fix: addProduct -> upsertProduct, reviewsCount -> reviews_count
      upsertProduct({
        ...formData,
        id: Math.random().toString(36).substr(2, 9),
        rating: 5,
        reviews_count: 0
      } as Product);
    }
    closeModal();
  };

  const openModal = (p?: Product) => {
    if (p) {
      setEditingProduct(p);
      setFormData(p);
    } else {
      setEditingProduct(null);
      setFormData({
        name: '',
        price: 0,
        category: 'Men',
        tag: 'None',
        description: '',
        stock: 0,
        images: ['https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=1000'],
        specs: {}
      });
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="p-8 space-y-8">
      <div className="flex justify-between items-center">
        <div>
