import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { AppProvider } from './store';
import Header from './components/Header';
import Footer from './components/Footer';
import Home from './pages/Home';
import Shop from './pages/Shop';
import ProductDetail from './pages/ProductDetail';
import Wishlist from './pages/Wishlist';
import LoadingScreen from './components/LoadingScreen';

// Admin Imports
import AdminLayout from './pages/Admin/AdminLayout';
import AdminDashboard from './pages/Admin/Dashboard';
import AdminProducts from './pages/Admin/Products';
import AdminBanners from './pages/Admin/Banners';
import AdminOrders from './pages/Admin/Orders';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [pathname]);
  return null;
};

const MainContent: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [exitAnimation, setExitAnimation] = useState(false);
  const location = useLocation();
  const isAdminPath = location.pathname.startsWith('/admin');

  useEffect(() => {
    const timer = setTimeout(() => {
      setExitAnimation(true);
      setTimeout(() => setIsLoading(false), 800);
    }, 2500);
    return () => clearTimeout(timer);
  }, []);

  if (isLoading) {
    return (
      <div className={exitAnimation ? 'animate-scaleOut' : ''}>
        <LoadingScreen />
      </div>
    );
  }

  // Admin section has its own layout, so we skip general Header/Footer
  if (isAdminPath) {
    return (
      <Routes>
        <Route element={<AdminLayout />}>
          <Route path="/admin" element={<AdminDashboard />} />
          <Route path="/admin/products" element={<AdminProducts />} />
          <Route path="/admin/banners" element={<AdminBanners />} />
          <Route path="/admin/orders" element={<AdminOrders />} />
        </Route>
      </Routes>
    );
  }

  return (
    <div className="flex flex-col min-h-screen animate-fadeIn">
      <Header />
      <div className="flex-grow">
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/shop" element={<Shop />} />
          <Route path="/product/:id" element={<ProductDetail />} />
          <Route path="/wishlist" element={<Wishlist />} />
          <Route path="*" element={<Home />} />
        </Routes>
      </div>
      <Footer />
    </div>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <Router>
        <ScrollToTop />
        <MainContent />
      </Router>
    </AppProvider>
  );
};

export default App;

import React, { useState } from 'react';
import { useStore } from '../../store';
import { Product, Category, ProductTag } from '../../types';
import { X, Search } from '../../components/Icons';

const AdminProducts: React.FC = () => {
  const { products, upsertProduct, deleteProduct } = useStore();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '',
    price: 0,
    category: 'Men',
    tag: 'None',
    description: '',
    stock: 0,
    images: [],
    specs: {}
  });

  const [imageInput, setImageInput] = useState('');
  const [specInput, setSpecInput] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const images = imageInput.split(',').map(s => s.trim()).filter(s => s !== '');
    let specs = {};
    try {
      specs = specInput ? JSON.parse(specInput) : {};
    } catch (err) {
      alert("Invalid JSON in Specifications field.");
      return;
    }

    const payload = {
      ...formData,
      images,
      specs,
      id: editingProduct ? editingProduct.id : Math.random().toString(36).substr(2, 9),
      rating: editingProduct ? editingProduct.rating : 5,
      reviews_count: editingProduct ? editingProduct.reviews_count : 0
    } as Product;

    await upsertProduct(payload);
    closeModal();
  };

  const openModal = (p?: Product) => {
    if (p) {
      setEditingProduct(p);
      setFormData(p);
      setImageInput(p.images.join(', '));
      setSpecInput(JSON.stringify(p.specs, null, 2));
    } else {
      setEditingProduct(null);
      setFormData({
        name: '',
        price: 0,
        category: 'Men',
        tag: 'None',
        description: '',
        stock: 0,
        images: [],
        specs: {}
      });
      setImageInput('');
      setSpecInput('{}');
    }
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const filtered = products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase()));

  return (
    <div className="p-12 space-y-12 animate-fadeIn">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-4xl font-serif mb-4">Inventory Vault</h1>
