export type ProductTag = 'Latest' | 'Best Seller' | 'Offer' | 'New Arrival' | 'None';

export interface KeyFeature {
  title: string;
  description: string;
}

export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  original_price?: number;
  category: string; // Changed from fixed union to string for dynamic support
  images: string[];
  specs: Record<string, string>;
  key_features: KeyFeature[]; // New field
  tag: ProductTag;
  stock: number;
  rating: number;
  reviews_count: number;
  created_at?: string;
}

export interface Banner {
  id: string;
  title: string;
  subtitle: string;
  image_url: string;
  tag_label: string;
  display_order: number;
}

export interface OrderItem {
  id: string;
  product_id: string;
  name: string;
  price: number;
  quantity: number;
  image: string;
}

export interface Order {
  id: string;
  user_name: string;
  user_email: string;
  items: OrderItem[];
  total_amount: number;
  status: 'Pending' | 'Artisan Prep' | 'Shipped' | 'Delivered';
  created_at: string;
}

export interface Category {
  id: string;
  name: string;
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product, Banner, Order, Category } from './types';
import { supabase } from './supabase';

interface AppState {
  products: Product[];
  banners: Banner[];
  orders: Order[];
  categories: Category[]; // Dynamic categories
  wishlist: string[];
  isLoading: boolean;

  // Mutations
  fetchData: () => Promise<void>;
  upsertProduct: (p: Partial<Product>) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;
  upsertBanner: (b: Partial<Banner>) => Promise<void>;
  deleteBanner: (id: string) => Promise<void>;
  upsertCategory: (c: Partial<Category>) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;
  updateOrderStatus: (id: string, status: Order['status']) => Promise<void>;
  toggleWishlist: (id: string) => void;
}

const AppContext = createContext<AppState | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>([]);
  const [banners, setBanners] = useState<Banner[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [wishlist, setWishlist] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [pRes, bRes, oRes, cRes] = await Promise.all([
        supabase.from('products').select('*').order('created_at', { ascending: false }),
        supabase.from('banners').select('*').order('display_order', { ascending: true }),
        supabase.from('orders').select('*').order('created_at', { ascending: false }),
        supabase.from('categories').select('*').order('name', { ascending: true })
      ]);

      if (pRes.data) setProducts(pRes.data);
      if (bRes.data) setBanners(bRes.data);
      if (oRes.data) setOrders(oRes.data);
      if (cRes.data) {
        setCategories(cRes.data);
      } else {
        // Default categories if table is empty
        setCategories([
          { id: '1', name: 'Luxury Series' },
          { id: '2', name: 'Wall Clocks' },
          { id: '3', name: 'Men' },
          { id: '4', name: 'Women' }
        ]);
      }
    } catch (err) {
      console.error("Error fetching AEVO data:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const upsertProduct = async (p: Partial<Product>) => {
    const { error } = await supabase.from('products').upsert(p);
    if (!error) await fetchData();
  };

  const deleteProduct = async (id: string) => {
    const { error } = await supabase.from('products').delete().eq('id', id);
    if (!error) await fetchData();
  };

  const upsertBanner = async (b: Partial<Banner>) => {
    const { error } = await supabase.from('banners').upsert(b);
    if (!error) await fetchData();
  };

  const deleteBanner = async (id: string) => {
    const { error } = await supabase.from('banners').delete().eq('id', id);
    if (!error) await fetchData();
  };

  const upsertCategory = async (c: Partial<Category>) => {
    const { error } = await supabase.from('categories').upsert(c);
    if (!error) await fetchData();
  };

  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (!error) await fetchData();
  };

  const updateOrderStatus = async (id: string, status: Order['status']) => {
    const { error } = await supabase.from('orders').update({ status }).eq('id', id);
    if (!error) await fetchData();
  };

  const toggleWishlist = (id: string) => {
    setWishlist(prev => prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]);
  };

  return (
    <AppContext.Provider value={{
      products, banners, orders, wishlist, isLoading, categories,
      fetchData, upsertProduct, deleteProduct, upsertBanner, deleteBanner, 
      upsertCategory, deleteCategory, updateOrderStatus, toggleWishlist
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useStore must be used within AppProvider');
  return context;
};

