  }, [onClose]);

  return (
    <div className="fixed bottom-12 right-12 z-[600] animate-fadeInUp">
      <div className={`px-8 py-4 rounded-2xl border backdrop-blur-xl shadow-2xl flex items-center space-x-4 ${
