      }`}>
        <div className={`w-2 h-2 rounded-full ${type === 'success' ? 'bg-emerald-500' : 'bg-red-500'} animate-pulse`} />
        <span className="text-[10px] font-black uppercase tracking-[0.3em]">{message}</span>
      </div>
    </div>
  );
};

export default Toast;

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product, Banner, Order, Category } from './types';
import { supabase } from './supabase';
import { INITIAL_PRODUCTS, INITIAL_BANNERS, MOCK_ORDERS } from './constants';

interface AppState {
  products: Product[];
  banners: Banner[];
  orders: Order[];
  categories: Category[];
  wishlist: string[];
  isLoading: boolean;

  fetchData: () => Promise<void>;
  upsertProduct: (p: Product) => Promise<void>;
  deleteProduct: (id: string) => Promise<void>;
  upsertBanner: (b: Banner) => Promise<void>;
  deleteBanner: (id: string) => Promise<void>;
  upsertCategory: (c: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;
  updateOrderStatus: (id: string, status: Order['status']) => Promise<void>;
  toggleWishlist: (id: string) => void;
}

const AppContext = createContext<AppState | undefined>(undefined);

const LOCAL_STORAGE_KEY = 'aevo_vault_v2';

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [products, setProducts] = useState<Product[]>(() => {
    const cached = localStorage.getItem(`${LOCAL_STORAGE_KEY}_products`);
    return cached ? JSON.parse(cached) : INITIAL_PRODUCTS;
  });
  const [banners, setBanners] = useState<Banner[]>(() => {
    const cached = localStorage.getItem(`${LOCAL_STORAGE_KEY}_banners`);
    return cached ? JSON.parse(cached) : INITIAL_BANNERS;
  });
  const [orders, setOrders] = useState<Order[]>(() => {
    const cached = localStorage.getItem(`${LOCAL_STORAGE_KEY}_orders`);
    return cached ? JSON.parse(cached) : MOCK_ORDERS;
  });
  const [categories, setCategories] = useState<Category[]>(() => {
    const cached = localStorage.getItem(`${LOCAL_STORAGE_KEY}_categories`);
    return cached ? JSON.parse(cached) : [
      { id: '1', name: 'Luxury Series' },
      { id: '2', name: 'Wall Clocks' },
      { id: '3', name: 'Men' },
      { id: '4', name: 'Women' },
      { id: '5', name: 'Smart Clocks' }
    ];
  });

  const [wishlist, setWishlist] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);

  // Persistence hooks
  useEffect(() => localStorage.setItem(`${LOCAL_STORAGE_KEY}_products`, JSON.stringify(products)), [products]);
  useEffect(() => localStorage.setItem(`${LOCAL_STORAGE_KEY}_banners`, JSON.stringify(banners)), [banners]);
  useEffect(() => localStorage.setItem(`${LOCAL_STORAGE_KEY}_orders`, JSON.stringify(orders)), [orders]);
  useEffect(() => localStorage.setItem(`${LOCAL_STORAGE_KEY}_categories`, JSON.stringify(categories)), [categories]);

  const fetchData = async () => {
    try {
      const [pRes, bRes, oRes, cRes] = await Promise.all([
        supabase.from('products').select('*').order('created_at', { ascending: false }),
        supabase.from('banners').select('*').order('display_order', { ascending: true }),
        supabase.from('orders').select('*').order('created_at', { ascending: false }),
        supabase.from('categories').select('*').order('name', { ascending: true })
      ]);

      if (pRes.data && pRes.data.length > 0) setProducts(pRes.data);
      if (bRes.data && bRes.data.length > 0) setBanners(bRes.data);
      if (oRes.data && oRes.data.length > 0) setOrders(oRes.data);
      if (cRes.data && cRes.data.length > 0) setCategories(cRes.data);
    } catch (err) {
      console.warn("AEVO: Database sync unavailable, using local vault.");
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const upsertProduct = async (p: Product) => {
    setProducts(prev => {
      const exists = prev.find(item => item.id === p.id);
      if (exists) return prev.map(item => item.id === p.id ? p : item);
      return [p, ...prev];
    });
    try { await supabase.from('products').upsert(p); } catch (e) {}
  };

  const deleteProduct = async (id: string) => {
    setProducts(prev => prev.filter(p => p.id !== id));
    try { await supabase.from('products').delete().eq('id', id); } catch (e) {}
  };

  const upsertBanner = async (b: Banner) => {
    setBanners(prev => {
      const exists = prev.find(item => item.id === b.id);
      if (exists) return prev.map(item => item.id === b.id ? b : item);
      return [...prev, b];
    });
    try { await supabase.from('banners').upsert(b); } catch (e) {}
  };

  const deleteBanner = async (id: string) => {
    setBanners(prev => prev.filter(b => b.id !== id));
    try { await supabase.from('banners').delete().eq('id', id); } catch (e) {}
  };

  const upsertCategory = async (c: Category) => {
    setCategories(prev => {
      const exists = prev.find(item => item.id === c.id);
      if (exists) return prev.map(item => item.id === c.id ? c : item);
      return [...prev, c];
    });
    try { await supabase.from('categories').upsert(c); } catch (e) {}
  };

  const deleteCategory = async (id: string) => {
    setCategories(prev => prev.filter(c => c.id !== id));
    try { await supabase.from('categories').delete().eq('id', id); } catch (e) {}
  };

  const updateOrderStatus = async (id: string, status: Order['status']) => {
    setOrders(prev => prev.map(o => o.id === id ? { ...o, status } : o));
    try { await supabase.from('orders').update({ status }).eq('id', id); } catch (e) {}
  };

  const toggleWishlist = (id: string) => {
    setWishlist(prev => prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]);
  };

  return (
    <AppContext.Provider value={{
      products, banners, orders, wishlist, isLoading, categories,
      fetchData, upsertProduct, deleteProduct, upsertBanner, deleteBanner, 
      upsertCategory, deleteCategory, updateOrderStatus, toggleWishlist
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useStore must be used within AppProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useStore } from '../../store';
import { Product, ProductTag, KeyFeature, Category } from '../../types';
import { X, Search, ChevronRight, Star, ShoppingBag } from '../../components/Icons';
import ConfirmDialog from '../../components/ConfirmDialog';
import Toast from '../../components/Toast';

const AdminProducts: React.FC = () => {
  const { products, categories, upsertProduct, deleteProduct, upsertCategory, deleteCategory } = useStore();

  // Modals & Feedback
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [confirm, setConfirm] = useState<{ title: string, message: string, onConfirm: () => void } | null>(null);

  // Form States
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [formData, setFormData] = useState<Partial<Product>>({});
  const [specs, setSpecs] = useState<{ key: string, value: string }[]>([]);
  const [features, setFeatures] = useState<KeyFeature[]>([]);
  const [imageUrls, setImageUrls] = useState<string[]>(['']);
  const [newCatName, setNewCatName] = useState('');

  const openModal = (p?: Product) => {
    if (p) {
      setEditingProduct(p);
      setFormData({ ...p });
      setSpecs(Object.entries(p.specs || {}).map(([key, value]) => ({ key, value })));
      setFeatures(p.key_features || []);
      setImageUrls(p.images.length > 0 ? p.images : ['']);
    } else {
      setEditingProduct(null);
      setFormData({
        name: '',
        price: 0,
        category: categories.length > 0 ? categories[0].name : 'Luxury Series',
        tag: 'None',
        description: '',
        stock: 0,
        images: []
      });
      setSpecs([{ key: 'Movement', value: '' }, { key: 'Material', value: '' }]);
      setFeatures([{ title: '', description: '' }]);
      setImageUrls(['']);
    }
    setIsModalOpen(true);
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();

    const specsObj: Record<string, string> = {};
    specs.forEach(s => { if(s.key) specsObj[s.key] = s.value; });

    const finalProduct = {
      ...formData,
      images: imageUrls.filter(url => url.trim() !== ''),
      specs: specsObj,
      key_features: features.filter(f => f.title.trim() !== ''),
      id: editingProduct ? editingProduct.id : Math.random().toString(36).substr(2, 9),
      rating: editingProduct ? editingProduct.rating : 5,
      reviews_count: editingProduct ? editingProduct.reviews_count : 0,
      created_at: editingProduct ? editingProduct.created_at : new Date().toISOString()
    } as Product;

    await upsertProduct(finalProduct);
    setToast({ message: editingProduct ? "Masterpiece Recalibrated" : "New Piece Enrolled", type: 'success' });
    setIsModalOpen(false);
  };

  const triggerDeleteProduct = (id: string, name: string) => {
    setConfirm({
      title: "Decommission Piece",
      message: `Are you certain you wish to remove the "${name}" from the active vault? This action is irreversible.`,
      onConfirm: async () => {
        await deleteProduct(id);
        setToast({ message: "Asset Purged from Vault", type: 'success' });
      }
    });
  };

  const handleAddCategory = async () => {
    if (!newCatName) return;
    await upsertCategory({ id: Math.random().toString(36).substr(2, 9), name: newCatName });
    setNewCatName('');
    setToast({ message: "New Series Protocol Authorized", type: 'success' });
  };

  const triggerDeleteCategory = (id: string, name: string) => {
    setConfirm({
      title: "Archive Series Protocol",
      message: `Decommissioning the "${name}" series? Products using this category will remain, but the series will be removed from registry.`,
      onConfirm: async () => {
        await deleteCategory(id);
        setToast({ message: "Series Protocol Terminated", type: 'success' });
      }
    });
  };

  return (
    <div className="p-12 space-y-12 animate-fadeIn bg-[#0F0F0F]">
      {/* Header Controls */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6">
        <div>
          <h1 className="text-4xl font-serif mb-4">Inventory Vault</h1>
          <p className="text-white/40 text-[10px] uppercase tracking-[0.5em]">Curate the Portfolio of Fine Instruments</p>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={() => setIsCategoryModalOpen(true)}
            className="bg-white/5 text-[#C5A059] px-8 py-4 rounded-full text-[10px] font-bold uppercase tracking-widest border border-[#C5A059]/20 hover:bg-[#C5A059]/10 transition-all"
          >
            Manage Series
          </button>
          <button 
            onClick={() => openModal()}
            className="bg-[#C5A059] text-white px-10 py-4 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-2xl hover:scale-105 transition-all"
          >
            Commission New Piece
          </button>
        </div>
      </div>

      {/* Search Protocol */}
      <div className="relative">
        <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-white/20 w-5 h-5" />
        <input 
          type="text" 
          placeholder="SEARCH ARCHIVES..."
          className="w-full pl-16 pr-8 py-5 bg-[#1A1918] border border-white/5 rounded-2xl text-[10px] uppercase tracking-[0.3em] font-bold text-white focus:outline-none focus:border-[#C5A059] transition-all"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Vault Table */}
      <div className="bg-[#1A1918] border border-white/5 rounded-[2.5rem] overflow-hidden shadow-2xl">
        <table className="w-full text-left">
          <thead>
            <tr className="text-[9px] uppercase tracking-[0.3em] text-white/20 border-b border-white/5">
              <th className="px-10 py-6 font-bold">Timepiece</th>
              <th className="px-10 py-6 font-bold">Series</th>
              <th className="px-10 py-6 font-bold">Valuation</th>
              <th className="px-10 py-6 font-bold">Allocation</th>
              <th className="px-10 py-6 font-bold">Protocols</th>
