import React, { useState } from 'react';
import { useStore } from '../../store';
import { Product, ProductTag, KeyFeature } from '../../types';
import { X, Search, Plus, Trash2, Edit3, Image as ImageIcon, Star } from '../../components/Icons';
import ConfirmDialog from '../../components/ConfirmDialog';
import Toast from '../../components/Toast';

const AdminProducts: React.FC = () => {
  const { products, categories, upsertProduct, deleteProduct, upsertCategory, deleteCategory } = useStore();

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [confirm, setConfirm] = useState<{ title: string, message: string, onConfirm: () => void } | null>(null);

  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [formData, setFormData] = useState<Partial<Product>>({});
  const [specs, setSpecs] = useState<{ key: string, value: string }[]>([]);
  const [features, setFeatures] = useState<KeyFeature[]>([]);
  const [colors, setColors] = useState<string[]>([]);
  const [imageUrls, setImageUrls] = useState<string[]>(['']);
  const [newCatName, setNewCatName] = useState('');

  const openModal = (p?: Product) => {
    if (p) {
      setEditingProduct(p);
      setFormData({ ...p });
      setSpecs(Object.entries(p.specs || {}).map(([key, value]) => ({ key, value })));
      setFeatures(p.key_features || []);
      setColors(p.colors || []);
      setImageUrls(p.images.length > 0 ? p.images : ['']);
    } else {
      setEditingProduct(null);
      setFormData({
        name: '', price: 0, original_price: 0, category: categories.length > 0 ? categories[0].name : 'Luxury Series',
        tag: 'Latest', description: '', stock: 10, images: []
      });
      setSpecs([{ key: 'Movement', value: '' }, { key: 'Material', value: '' }]);
      setFeatures([{ title: '', description: '' }]);
      setColors(['Silver', 'Gold']);
      setImageUrls(['']);
    }
    setIsModalOpen(true);
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();

    const specsObj: Record<string, string> = {};
    specs.forEach(s => { if(s.key.trim()) specsObj[s.key] = s.value; });

    const finalProduct = {
      ...formData,
      images: imageUrls.filter(url => url.trim() !== ''),
      colors: colors.filter(c => c.trim() !== ''),
      specs: specsObj,
      key_features: features.filter(f => f.title.trim() !== ''),
      id: editingProduct ? editingProduct.id : `p-${Date.now()}`,
      rating: editingProduct ? editingProduct.rating : 5,
      reviews_count: editingProduct ? editingProduct.reviews_count : 0,
      created_at: editingProduct ? editingProduct.created_at : new Date().toISOString()
    } as Product;

    const syncSuccess = await upsertProduct(finalProduct);
    if (syncSuccess) {
      setToast({ message: editingProduct ? "Piece Refined" : "Piece Enrolled Successfully", type: 'success' });
    } else {
      setToast({ message: "Saved Locally. Database sync failure.", type: 'error' });
    }
    setIsModalOpen(false);
  };

  const handleAddCategory = async () => {
    if (!newCatName.trim()) return;
    const success = await upsertCategory({ id: `cat-${Date.now()}`, name: newCatName });
    if (success) { setNewCatName(''); setToast({ message: "Series Registered", type: 'success' }); }
  };

  return (
    <div className="space-y-6 md:space-y-10 animate-fadeIn pb-24">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-black/[0.05] pb-6 md:pb-8">
        <div>
          <h1 className="text-2xl md:text-3xl lg:text-4xl font-serif text-black italic leading-tight">Inventory Registry</h1>
          <p className="text-[#A68E74] text-[8px] md:text-[10px] uppercase tracking-[0.4em] font-black mt-1">Archive Management Portal</p>
        </div>
        <div className="flex w-full sm:w-auto gap-3">
          <button 
            onClick={() => setIsCategoryModalOpen(true)} 
            className="flex-1 sm:flex-none px-4 md:px-6 py-3 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-widest border border-black/10 bg-white hover:bg-black/5 transition-all active:scale-95"
          >
            Manage Series
          </button>
          <button 
            onClick={() => openModal()} 
            className="flex-1 sm:flex-none bg-black text-white px-5 md:px-8 py-3 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-widest shadow-xl hover:shadow-black/10 hover:-translate-y-0.5 transition-all active:scale-95"
          >
            Enroll Piece
          </button>
        </div>
      </div>

      {/* Search Protocol */}
      <div className="relative group">
        <Search className="absolute left-4 md:left-6 top-1/2 -translate-y-1/2 text-black/20 w-4 h-4 md:w-5 md:h-5 transition-colors group-focus-within:text-[#A68E74]" />
        <input 
          type="text" 
