          className="w-full pl-12 md:pl-16 pr-4 md:pr-8 py-4 md:py-5 bg-white border border-black/10 rounded-xl md:rounded-2xl text-[9px] md:text-[11px] uppercase tracking-widest font-black outline-none focus:border-[#A68E74] shadow-sm transition-all"
          value={searchTerm} 
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Grid Display */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
        {products.filter(p => p.name.toLowerCase().includes(searchTerm.toLowerCase())).map(product => (
