              <div className="w-20 h-24 sm:w-full sm:h-48 lg:w-20 lg:h-24 bg-[#F9F7F5] rounded-xl overflow-hidden border border-black/5 flex-shrink-0 relative">
                <img src={product.images[0]} className="w-full h-full object-cover mix-blend-multiply opacity-80 group-hover:scale-110 transition-transform duration-1000" alt={product.name} />
                <div className="absolute inset-0 bg-black/0 group-hover:bg-black/5 transition-colors" />
              </div>
              <div className="flex-1 min-w-0 sm:mt-2 lg:mt-0">
                <span className="text-[7px] md:text-[8px] uppercase tracking-[0.4em] text-[#A68E74] font-black mb-1 block truncate">{product.category}</span>
                <h3 className="font-serif text-base md:text-lg text-black truncate italic leading-tight group-hover:text-[#A68E74] transition-colors">{product.name}</h3>
                <p className="text-[10px] md:text-[11px] font-bold text-black/40 mt-1">₹{product.price.toLocaleString('en-IN')}</p>
              </div>
