                  <Edit3 className="w-3.5 h-3.5 md:w-4 md:h-4" />
                </button>
                <button 
                  onClick={() => setConfirm({ title: "Purge Piece", message: "Are you certain you wish to purge this instrument from the registry?", onConfirm: () => deleteProduct(product.id) })} 
                  className="p-2 md:p-2.5 bg-red-50 text-red-500 rounded-lg md:rounded-xl hover:bg-red-500 hover:text-white transition-all active:scale-90"
                  title="Purge Piece"
                >
                  <Trash2 className="w-3.5 h-3.5 md:w-4 md:h-4" />
                </button>
              </div>
            </div>
          </div>
        ))}
        {products.length === 0 && (
          <div className="col-span-full py-32 text-center border-2 border-dashed border-black/5 rounded-[3rem]">
            <p className="text-black/20 font-serif italic text-xl">The vault is currently unoccupied.</p>
          </div>
