    if (!newCatName.trim()) return;
    const success = await upsertCategory({ id: `cat-${Date.now()}`, name: newCatName });
    if (success) { 
      setNewCatName(''); 
      setToast({ message: "Series Registered", type: 'success' }); 
    }
  };

  return (
    <div className="space-y-8 lg:space-y-12 animate-fadeIn pb-24">
