                               <input 
                                 placeholder="#FFFFFF" 
                                 className="flex-1 bg-transparent text-[9px] sm:text-[10px] font-mono outline-none border-b border-black/5 focus:border-[#A68E74] pb-1" 
                                 value={color.hex} 
                                 onChange={e => {
                                   const newColors = [...colors]; 
                                   newColors[i].hex = e.target.value; 
                                   setColors(newColors);
                                 }} 
                               />
                             </div>
