                <div className="w-6 h-px bg-[#A68E74]/30 mx-auto mt-2.5" />
             </div>

             {[...Array(12)].map((_, i) => (
               <div
                 key={i}
                 className="absolute w-px bg-[#A68E74]/20 origin-bottom"
                 style={{
                   height: i % 3 === 0 ? '12px' : '6px',
                   bottom: '50%',
