To fully initialize your **AEVO Atelier** database on Supabase, execute the following SQL script. This single block handles the authentication profiles, product registry, cinematic banners, order ledgers, and category hierarchies, while ensuring secure access control.

```sql
-- ==========================================
-- 1. CLEANUP (Optional - use if resetting)
-- ==========================================
-- DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
-- DROP FUNCTION IF EXISTS public.handle_new_user();
-- DROP TABLE IF EXISTS public.orders;
-- DROP TABLE IF EXISTS public.banners;
-- DROP TABLE IF EXISTS public.products;
-- DROP TABLE IF EXISTS public.categories;
-- DROP TABLE IF EXISTS public.profiles;

-- ==========================================
-- 2. TABLES SETTINGS
-- ==========================================

-- Profiles Table (Admin Management)
CREATE TABLE public.profiles (
  id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
  email TEXT,
  is_admin BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Categories Table
CREATE TABLE public.categories (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Products Table
CREATE TABLE public.products (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  price NUMERIC NOT NULL,
  original_price NUMERIC,
  category TEXT NOT NULL,
  images TEXT[] DEFAULT '{}',
  colors TEXT[] DEFAULT '{}', -- Format: "Name:#HEX"
  specs JSONB DEFAULT '{}',
  key_features JSONB DEFAULT '[]',
  tag TEXT DEFAULT 'None',
  stock INTEGER DEFAULT 0,
  rating NUMERIC DEFAULT 5,
  reviews_count INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Banners Table (Hero Showcase)
CREATE TABLE public.banners (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  subtitle TEXT,
  image_url TEXT NOT NULL,
  tag_label TEXT,
  display_order INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Orders Table
CREATE TABLE public.orders (
  id TEXT PRIMARY KEY,
  user_name TEXT NOT NULL,
  user_email TEXT NOT NULL,
  items JSONB NOT NULL DEFAULT '[]',
  total_amount NUMERIC NOT NULL,
  status TEXT DEFAULT 'Pending', -- Pending, Artisan Prep, Shipped, Delivered
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- ==========================================
-- 3. SECURITY (Row Level Security)
-- ==========================================

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.banners ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;

-- Profiles Policies
CREATE POLICY "Users can view own profile" ON public.profiles FOR SELECT USING (auth.uid() = id);

-- Products/Categories/Banners Policies (Public Read, Admin Write)
CREATE POLICY "Public Read Products" ON public.products FOR SELECT USING (true);
CREATE POLICY "Admin All Products" ON public.products FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

CREATE POLICY "Public Read Categories" ON public.categories FOR SELECT USING (true);
CREATE POLICY "Admin All Categories" ON public.categories FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

CREATE POLICY "Public Read Banners" ON public.banners FOR SELECT USING (true);
CREATE POLICY "Admin All Banners" ON public.banners FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

-- Orders Policies (Admin Only for Ledger)
CREATE POLICY "Admin All Orders" ON public.orders FOR ALL USING (
  EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND is_admin = true)
);

-- ==========================================
-- 4. AUTH AUTOMATION (Trigger)
-- ==========================================

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, email, is_admin)
  VALUES (new.id, new.email, FALSE);
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

-- ==========================================
-- 5. INITIAL SEED DATA
-- ==========================================

INSERT INTO public.categories (id, name) VALUES 
('1', 'Luxury Series'),
('2', 'Wall Clocks'),
('3', 'Men'),
('4', 'Women'),
('5', 'Smart Clocks');

INSERT INTO public.banners (id, title, subtitle, image_url, tag_label, display_order) VALUES 
('b1', 'The Platinum Standard', 'Limited release precision engineering', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?auto=format&fit=crop&q=1600', 'Latest Models', 1),
('b2', 'Timeless Interiors', 'Elevating the architecture of time', 'https://images.unsplash.com/photo-1495856458515-0637185db551?auto=format&fit=crop&q=1600', 'Best Selling', 2);
```

### Steps to Apply:
1.  Go to your **Supabase Dashboard**.
2.  Open the **SQL Editor** from the left sidebar.
3.  Click **New Query**.
4.  Paste the entire text above.
5.  Click **Run**.
6.  **Important**: After you sign up via your login screen for the first time, go to the `profiles` table in Supabase and manually toggle `is_admin` to `true` for your user account to gain full access to the Atelier Dashboard.

